transforms.code:
if len(value.data) > 1:
	rows = self.custom.selection.rows
	cols = self.custom.selection.cols
	rows.append(value.selectedRow)
	cols.append(value.selectedColumn)
else:
	rows = []
	cols = []

return {'rows': list(set(rows)), 'cols': list(set(cols))}

skipKeys = set([
	'chkItemId', 'chkItemGroupName', 'chkItemPath',
	'sortOrder', 'measNumber', 'dataTypeName', 'dataTypeIsNumeric',
	'engUnitName', 'summarySum', 'summaryAvg', 'summaryMin',
	'summaryMax', 'summaryStdDev', 'summaryRange',
	'lel', 'lcl', 'ldl', 'lsl', 'tgt', 'ucl', 'udl', 'uel', 'usl'
])

def styledCell(value, color):
	return {'value': value, 'style': {'marginTop': '2px', 'marginBottom': '2px', 'classes': 'kanoa/border', 'backgroundColor': color }}

data = system.kanoa.utilities.convertDatasetToJSON(value)

for row in data:
	numericKeys = [key for key in row.keys() if key not in skipKeys and row.get(key) is not None and row.get('dataTypeIsNumeric')]

	values = []
	for key in numericKeys:
		try:
			values.append(float(row[key]))
		except:
			pass

	if values:
		mean = system.math.mean(values)
		stdDev = system.math.standardDeviation(values)
		clcl = mean - (3 * stdDev)
		cucl = mean + (3 * stdDev)
	else:
		mean = None
		stdDev = None
		clcl = None
		cucl = None

	alerts = []

	for key in numericKeys:
		try:
			chkItemValue = float(row[key])
		except:
			continue

		if row.get('lsl') is not None and chkItemValue < row['lsl']:
			alerts.append('LSL')
			row[key] = styledCell(chkItemValue, '--kcRed-30')
		elif row.get('lcl') is not None and chkItemValue < row['lcl']:
			alerts.append('LCL')
			row[key] = styledCell(chkItemValue, '--kcOrange-30')
		elif row.get('usl') is not None and chkItemValue > row['usl']:
			alerts.append('USL')
			row[key] = styledCell(chkItemValue, '--kcRed-30')
		elif row.get('ucl') is not None and chkItemValue > row['ucl']:
			alerts.append('UCL')
			row[key] = styledCell(chkItemValue, '--kcOrange-30')
		elif clcl is not None and chkItemValue < clcl:
			alerts.append('cLCL')
			row[key] = styledCell(chkItemValue, '--kcYellow-30')
		elif cucl is not None and chkItemValue > cucl:
			alerts.append('cUCL')
			row[key] = styledCell(chkItemValue, '--kcYellow-30')

	row['Calc. LCL'] = clcl
	row['Calc. UCL'] = cucl

	alerts = set(alerts)

	if 'LSL' in alerts or 'USL' in alerts: row['Alert'] = {"icon": "material/warning", "toolTip": "Outside of spec limits", "color": "--kcRed-50"}
	elif 'LCL' in alerts or 'UCL' in alerts: row['Alert'] = {"icon": "material/warning", "toolTip": "Outside of control limits", "color": "--kcOrange-50"}
	elif 'cLCL' in alerts or 'cUCL' in alerts: row['Alert'] = {"icon": "material/warning", "toolTip": "Outside of calculated control limits", "color": "--kcYellow-50"}
	else: row['Alert'] = {"icon": "", "toolTip": "", "color": ""}

	row['points'] = {
		'points': values,
		'controlLimits': {
			'min': row.get('summaryMin'),
			'max': row.get('summaryMax'),
			'lsl': row.get('lsl'),
			'lcl': row.get('lcl') if row.get('lcl') is not None else clcl,
			'tgt': row.get('tgt'),
			'ucl': row.get('ucl') if row.get('ucl') is not None else cucl,
			'usl': row.get('usl'),
			'mean': row.get('summaryAvg'),
			'stdDev': row.get('summaryStdDev')
		}
	}

	row['chkItemPath'] = {'value': row['chkItemPath'], 'style': {'backgroundColor': '#FFFF00'}}

return data
